import React from 'react';
import './Header.css'; // Create and add your styles here

const Header = () => (
  <section id="header">
    <link href='https://fonts.googleapis.com/css?family=Radley' rel='stylesheet'></link>
    <h1>Hello, I'm Gems</h1>
    <img src="/img/gems1.png" alt="Gems" className="profile-pic" />
    <p>Web Developer by day,<br></br> Code Wizard by night.</p>
  </section>
);

export default Header;
